import React, { useState } from "react";
import { Helmet } from "react-helmet";
import "./styles.css";

function App() {
  // State for the contact form
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    message: ""
  });

  // Handle input change
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  // Handle form submission
  const handleSubmit = (e) => {
    e.preventDefault();
    alert(`Thank you, ${formData.name}! Your message has been sent.`);
    setFormData({ name: "", email: "", message: "" }); // Reset form
  };

  return (
    <div>
      {/* React Helmet for SEO and Metadata */}
      <Helmet>
        <title>Open Course Dashboard</title>
        <meta name="description" content="Explore high-quality open courses and enhance your learning journey." />
      </Helmet>

      {/* Navigation Bar */}
      <nav className="navbar">
        <h1>Open Course</h1>
        <ul>
          <li><a href="#courses">Courses</a></li>
          <li><a href="#about">About</a></li>
          <li><a href="#contact">Contact</a></li>
        </ul>
      </nav>

      {/* Hero Section */}
      <header className="hero">
        <h2>Welcome to Open Course</h2>
        <p>Discover free and open-source courses to boost your skills.</p>
      </header>

      {/* Course List Section */}
      <section id="courses" className="courses">
        <h3>Featured Courses</h3>
        <ul>
          <li><strong>React Basics</strong> - Learn the fundamentals of React.js.</li>
          <li><strong>JavaScript Essentials</strong> - Master the core concepts of JavaScript.</li>
          <li><strong>Python for Beginners</strong> - Start coding with Python.</li>
        </ul>
      </section>

      {/* About Section */}
      <section id="about" className="about">
        <h3>About Open Course</h3>
        <p>Open Course provides high-quality educational content for learners around the world.</p>
      </section>

      {/* Contact Section */}
      <section id="contact" className="contact">
        <h3>Contact Us</h3>
        <p>Have questions? Fill out the form below and we will get back to you.</p>

        <form onSubmit={handleSubmit} className="contact-form">
          <input
            type="text"
            name="name"
            placeholder="Your Name"
            value={formData.name}
            onChange={handleChange}
            required
          />
          <input
            type="email"
            name="email"
            placeholder="Your Email"
            value={formData.email}
            onChange={handleChange}
            required
          />
          <textarea
            name="message"
            placeholder="Your Message"
            value={formData.message}
            onChange={handleChange}
            required
          />
          <button type="submit">Send Message</button>
        </form>
      </section>

      {/* Footer */}
      {/* Footer */}
      <footer className="footer">
        <p>&copy; 2025 Open Course. All rights reserved.</p>
        <p>Made by Akhilesh</p>
      </footer>

    </div>
  );
}

export default App;
